package com.utility.billing.support;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import com.utility.billing.notification.NotificationService;

@Service
public class SupportService {
    private final JdbcTemplate jdbc;private final ObjectMapper json;private final NotificationService notifications;
    public SupportService(JdbcTemplate jdbc,ObjectMapper json,NotificationService notifications){this.jdbc=jdbc;this.json=json;this.notifications=notifications;}

    public Map<String,Object> summary(String actor){long user=actorId(actor);Map<String,Object> result=new LinkedHashMap<>();result.put("open",count("OPEN"));result.put("inProgress",count("IN_PROGRESS"));result.put("resolved",count("RESOLVED"));result.put("overdueSla",jdbc.queryForObject("SELECT COUNT(*) FROM ticket WHERE status IN ('OPEN','IN_PROGRESS') AND due_at<UTC_TIMESTAMP(6)",Long.class));result.put("mine",jdbc.queryForObject("SELECT COUNT(*) FROM ticket WHERE assigned_to=? AND status IN ('OPEN','IN_PROGRESS')",Long.class,user));return result;}

    public PageResult tickets(String query,String service,String status,String priority,String dateFrom,String dateTo,boolean mine,int page,int size,String actor){
        validatePage(page,size);long actorId=actorId(actor);StringBuilder where=new StringBuilder(" WHERE 1=1");List<Object> args=new ArrayList<>();
        if(query!=null&&!query.isBlank()){where.append(" AND LOWER(CONCAT_WS(' ',t.ticket_number,t.subject,t.category,t.status,t.priority,cp.customer_number,cp.full_name,s.name)) LIKE ?");args.add("%"+query.trim().toLowerCase(Locale.ROOT)+"%");}
        if(service!=null&&!service.isBlank()){where.append(" AND s.code=?");args.add(service.toUpperCase(Locale.ROOT));}
        if(status!=null&&!status.isBlank()){String v=status.toUpperCase(Locale.ROOT);if(!List.of("OPEN","IN_PROGRESS","RESOLVED","CLOSED").contains(v))throw bad("Unsupported ticket status");where.append(" AND t.status=?");args.add(v);}
        if(priority!=null&&!priority.isBlank()){String v=priority.toUpperCase(Locale.ROOT);if(!List.of("LOW","NORMAL","HIGH","URGENT").contains(v))throw bad("Unsupported ticket priority");where.append(" AND t.priority=?");args.add(v);}
        if(dateFrom!=null&&!dateFrom.isBlank()){where.append(" AND DATE(t.created_at)>=?");args.add(dateFrom);}
        if(dateTo!=null&&!dateTo.isBlank()){where.append(" AND DATE(t.created_at)<=?");args.add(dateTo);}
        if(mine){where.append(" AND t.assigned_to=?");args.add(actorId);}
        String from=" FROM ticket t JOIN customer_profile cp ON cp.user_id=t.customer_id JOIN utility_service s ON s.id=t.service_id LEFT JOIN support_profile sp ON sp.user_id=t.assigned_to";
        String select="SELECT t.id,t.ticket_number ticketNumber,t.customer_id customerId,cp.customer_number customerNumber,cp.full_name customerName,cp.phone customerPhone,t.service_id serviceId,s.code serviceCode,s.name service,t.category,t.subject,t.description,t.status,t.priority,t.assigned_to assignedTo,COALESCE(sp.full_name,'Unassigned') assigneeName,t.escalated,t.due_at dueAt,t.resolved_at resolvedAt,t.closed_at closedAt,t.rating,t.created_at createdAt,t.updated_at updatedAt";
        long total=jdbc.queryForObject("SELECT COUNT(*)"+from+where,Long.class,args.toArray());List<Object> paged=new ArrayList<>(args);paged.add(size);paged.add(page*size);
        return new PageResult(jdbc.queryForList(select+from+where+" ORDER BY CASE t.status WHEN 'OPEN' THEN 0 WHEN 'IN_PROGRESS' THEN 1 WHEN 'RESOLVED' THEN 2 ELSE 3 END, CASE t.priority WHEN 'URGENT' THEN 0 WHEN 'HIGH' THEN 1 WHEN 'NORMAL' THEN 2 ELSE 3 END,t.due_at,t.created_at DESC LIMIT ? OFFSET ?",paged.toArray()),page,size,total);
    }

    public Map<String,Object> ticket(long id,String actor){Map<String,Object> row=getTicket(id);List<Map<String,Object>> comments=jdbc.queryForList("SELECT tc.id,tc.body,tc.internal,tc.created_at createdAt,u.email authorEmail,COALESCE(sp.full_name,cp.full_name,ap.full_name,u.email) authorName FROM ticket_comment tc JOIN users u ON u.id=tc.author_id LEFT JOIN support_profile sp ON sp.user_id=u.id LEFT JOIN customer_profile cp ON cp.user_id=u.id LEFT JOIN admin_profile ap ON ap.user_id=u.id WHERE tc.ticket_id=? AND tc.internal=FALSE ORDER BY tc.created_at",id);row.put("comments",comments);row.put("internalNotes",jdbc.queryForList("SELECT tc.id,tc.body,tc.created_at createdAt,u.email authorEmail,COALESCE(sp.full_name,u.email) authorName FROM ticket_comment tc JOIN users u ON u.id=tc.author_id LEFT JOIN support_profile sp ON sp.user_id=u.id WHERE tc.ticket_id=? AND tc.internal=TRUE ORDER BY tc.created_at",id));return row;}

    @Transactional public Map<String,Object> assignToSelf(long id,String actor,String ip){long user=actorId(actor);Map<String,Object> old=getTicket(id);if(List.of("CLOSED","RESOLVED").contains(old.get("status")))throw conflict("Resolved or closed tickets cannot be assigned");jdbc.update("UPDATE ticket SET assigned_to=? WHERE id=?",user,id);audit(user,"TICKET_ASSIGNED_TO_SELF","ticket",id,ip,old,getTicket(id));return getTicket(id);}

    @Transactional public Map<String,Object> updateStatus(long id,String status,String actor,String ip){long user=actorId(actor);String next=status.toUpperCase(Locale.ROOT);if(!List.of("OPEN","IN_PROGRESS","RESOLVED","CLOSED").contains(next))throw bad("Unsupported ticket status");Map<String,Object> old=getTicket(id);String previous=old.get("status").toString();if(previous.equals(next))return old;boolean valid=switch(previous){case "OPEN"->next.equals("IN_PROGRESS")||next.equals("RESOLVED");case "IN_PROGRESS"->next.equals("RESOLVED");case "RESOLVED"->next.equals("CLOSED")||(next.equals("OPEN")&&reopenAllowed(old));case "CLOSED"->next.equals("OPEN")&&reopenAllowed(old);default->false;};if(!valid)throw conflict("Ticket status transition is not allowed");if(next.equals("OPEN")&&(previous.equals("CLOSED")||previous.equals("RESOLVED")))jdbc.update("UPDATE ticket SET status='OPEN',assigned_to=NULL,resolved_at=NULL,closed_at=NULL,due_at=DATE_ADD(UTC_TIMESTAMP(6),INTERVAL sla_minutes MINUTE) WHERE id=?",id);else if(next.equals("RESOLVED"))jdbc.update("UPDATE ticket SET status='RESOLVED',resolved_at=UTC_TIMESTAMP(6),closed_at=NULL WHERE id=?",id);else if(next.equals("CLOSED"))jdbc.update("UPDATE ticket SET status='CLOSED',closed_at=UTC_TIMESTAMP(6) WHERE id=?",id);else jdbc.update("UPDATE ticket SET status=? WHERE id=?",next,id);Map<String,Object> result=getTicket(id);audit(user,"TICKET_STATUS_CHANGED","ticket",id,ip,old,result);if(next.equals("RESOLVED")||next.equals("CLOSED"))notifyCustomer(((Number)old.get("customerId")).longValue(),"Ticket status updated","Ticket "+old.get("ticketNumber")+" is now "+next.toLowerCase(Locale.ROOT)+".");return result;}

    @Transactional public Map<String,Object> comment(long id,String body,boolean internal,String actor,String ip){long user=actorId(actor);if(body==null||body.isBlank()||body.length()>4000)throw bad("Comment must contain 1 to 4000 characters");Map<String,Object> old=getTicket(id);jdbc.update("INSERT INTO ticket_comment(ticket_id,author_id,body,internal) VALUES (?,?,?,?)",id,user,body.trim(),internal);Long commentId=jdbc.queryForObject("SELECT LAST_INSERT_ID()",Long.class);Map<String,Object> next=jdbc.queryForMap("SELECT tc.id,tc.ticket_id ticketId,tc.body,tc.internal,tc.created_at createdAt,u.email authorEmail FROM ticket_comment tc JOIN users u ON u.id=tc.author_id WHERE tc.id=?",commentId);audit(user,internal?"TICKET_INTERNAL_NOTE_ADDED":"TICKET_COMMENT_ADDED","ticket",id,ip,null,next);if(!internal)notifyCustomer(((Number)old.get("customerId")).longValue(),"Ticket update", "A support comment was added to ticket "+old.get("ticketNumber"));return next;}

    @Transactional public Map<String,Object> escalate(long id,String actor,String ip){long user=actorId(actor);Map<String,Object> old=getTicket(id);jdbc.update("UPDATE ticket SET escalated=TRUE,priority='URGENT' WHERE id=?",id);Map<String,Object> next=getTicket(id);audit(user,"TICKET_ESCALATED","ticket",id,ip,old,next);return next;}

    public Map<String,Object> customerContext(long customerId){Map<String,Object> result=new LinkedHashMap<>();try{result.put("profile",jdbc.queryForMap("SELECT customer_number customerNumber,full_name fullName,phone FROM customer_profile WHERE user_id=?",customerId));}catch(org.springframework.dao.EmptyResultDataAccessException ex){throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Customer not found");}result.put("connections",jdbc.queryForList("SELECT c.id connectionId,c.meter_number meterNumber,c.address,c.status,s.name service,ct.name connectionType FROM connection c JOIN utility_service s ON s.id=c.service_id JOIN connection_type ct ON ct.id=c.connection_type_id WHERE c.customer_id=?",customerId));result.put("bills",jdbc.queryForList("SELECT b.id,b.bill_number billNumber,b.cycle,b.total_amount totalAmount,b.paid_amount paidAmount,b.status,b.due_date dueDate,c.meter_number meterNumber,s.name service FROM bill b JOIN connection c ON c.id=b.connection_id JOIN utility_service s ON s.id=c.service_id WHERE c.customer_id=? ORDER BY b.issue_date DESC LIMIT 20",customerId));result.put("payments",jdbc.queryForList("SELECT p.transaction_id transactionId,p.amount,p.method,p.status,p.paid_at paidAt,b.bill_number billNumber FROM payment p JOIN bill b ON b.id=p.bill_id JOIN connection c ON c.id=b.connection_id WHERE c.customer_id=? ORDER BY p.created_at DESC LIMIT 20",customerId));return result;}

    public PageResult customerTickets(String email,int page,int size){long customer=customerId(email);validatePage(page,size);String base="SELECT t.id,t.ticket_number ticketNumber,s.name service,t.category,t.subject,t.status,t.priority,t.due_at dueAt,t.resolved_at resolvedAt,t.rating,t.created_at createdAt FROM ticket t JOIN utility_service s ON s.id=t.service_id WHERE t.customer_id=?";long total=jdbc.queryForObject("SELECT COUNT(*) FROM ticket WHERE customer_id=?",Long.class,customer);return new PageResult(jdbc.queryForList(base+" ORDER BY t.created_at DESC LIMIT ? OFFSET ?",customer,size,page*size),page,size,total);}

    @Transactional public Map<String,Object> createCustomerTicket(String email,long serviceId,String category,String subject,String description,String ip){long customer=customerId(email);String normalized=category.toUpperCase(Locale.ROOT);if(!List.of("BILLING_DISPUTE","WRONG_READING","NO_SUPPLY","LEAKAGE","NEW_CONNECTION","PAYMENT_FAILURE","OTHER").contains(normalized))throw bad("Unsupported ticket category");Integer active=jdbc.queryForObject("SELECT COUNT(*) FROM utility_service WHERE id=? AND active=TRUE",Integer.class,serviceId);if(active==null||active==0)throw bad("Choose an active utility service");String number="TKT-"+java.util.UUID.randomUUID().toString().replace("-","").substring(0,16).toUpperCase(Locale.ROOT);long sla=normalized.equals("NO_SUPPLY")||normalized.equals("LEAKAGE")?8*60:24*60;jdbc.update("INSERT INTO ticket(ticket_number,customer_id,service_id,category,subject,description,status,priority,due_at,sla_minutes) VALUES (?,?,?,?,?,?,'OPEN',?,DATE_ADD(UTC_TIMESTAMP(6),INTERVAL ? MINUTE),?)",number,customer,serviceId,normalized,subject.trim(),description.trim(),sla<=480?"HIGH":"NORMAL",sla,sla);Long id=jdbc.queryForObject("SELECT LAST_INSERT_ID()",Long.class);Map<String,Object> result=getTicket(id);audit(customer,"TICKET_CREATED","ticket",id,ip,null,result);notifications.notify(customer,"Support ticket opened","Ticket "+number+" has been opened.","TICKET_OPENED_"+id,true);return result;}

    public Map<String,Object> customerTicket(long id,String email){long customer=customerId(email);Map<String,Object> row=ownedTicket(id,customer);row.put("comments",jdbc.queryForList("SELECT tc.id,tc.body,tc.created_at createdAt,u.email authorEmail,COALESCE(sp.full_name,cp.full_name,u.email) authorName FROM ticket_comment tc JOIN users u ON u.id=tc.author_id LEFT JOIN support_profile sp ON sp.user_id=u.id LEFT JOIN customer_profile cp ON cp.user_id=u.id WHERE tc.ticket_id=? AND tc.internal=FALSE ORDER BY tc.created_at",id));return row;}

    @Transactional public Map<String,Object> customerComment(long id,String email,String body,String ip){long customer=customerId(email);Map<String,Object> old=ownedTicket(id,customer);if(!List.of("OPEN","IN_PROGRESS","RESOLVED").contains(old.get("status")))throw conflict("This ticket no longer accepts comments");if(body==null||body.isBlank()||body.length()>4000)throw bad("Comment must contain 1 to 4000 characters");jdbc.update("INSERT INTO ticket_comment(ticket_id,author_id,body,internal) VALUES (?,?,?,FALSE)",id,customer,body.trim());Long commentId=jdbc.queryForObject("SELECT LAST_INSERT_ID()",Long.class);Map<String,Object> result=jdbc.queryForMap("SELECT id,body,created_at createdAt FROM ticket_comment WHERE id=?",commentId);result.put("ticketId",id);audit(customer,"TICKET_CUSTOMER_COMMENT_ADDED","ticket",id,ip,null,result);return result;}

    @Transactional public Map<String,Object> rateCustomerTicket(long id,String email,int rating,String ip){long customer=customerId(email);Map<String,Object> old=ownedTicket(id,customer);if(rating<1||rating>5)throw bad("Rating must be from 1 to 5");if(!List.of("RESOLVED","CLOSED").contains(old.get("status")))throw conflict("Rate the ticket after it is resolved");if(old.get("rating")!=null)throw conflict("This ticket has already been rated");jdbc.update("UPDATE ticket SET rating=? WHERE id=? AND customer_id=? AND rating IS NULL",rating,id,customer);Map<String,Object> next=ownedTicket(id,customer);audit(customer,"TICKET_RATED","ticket",id,ip,old,next);return next;}

    private Map<String,Object> ownedTicket(long id,long customer){try{return jdbc.queryForMap("SELECT t.id,t.ticket_number ticketNumber,t.customer_id customerId,cp.customer_number customerNumber,cp.full_name customerName,s.name service,t.category,t.subject,t.description,t.status,t.priority,t.due_at dueAt,t.resolved_at resolvedAt,t.closed_at closedAt,t.rating,t.created_at createdAt FROM ticket t JOIN customer_profile cp ON cp.user_id=t.customer_id JOIN utility_service s ON s.id=t.service_id WHERE t.id=? AND t.customer_id=?",id,customer);}catch(org.springframework.dao.EmptyResultDataAccessException ex){throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Ticket not found");}}

    private Map<String,Object> getTicket(long id){try{return jdbc.queryForMap("SELECT t.id,t.ticket_number ticketNumber,t.customer_id customerId,cp.customer_number customerNumber,cp.full_name customerName,cp.phone customerPhone,t.service_id serviceId,s.code serviceCode,s.name service,t.category,t.subject,t.description,t.status,t.priority,t.assigned_to assignedTo,COALESCE(sp.full_name,'Unassigned') assigneeName,t.escalated,t.due_at dueAt,t.resolved_at resolvedAt,t.closed_at closedAt,t.rating,t.created_at createdAt FROM ticket t JOIN customer_profile cp ON cp.user_id=t.customer_id JOIN utility_service s ON s.id=t.service_id LEFT JOIN support_profile sp ON sp.user_id=t.assigned_to WHERE t.id=?",id);}catch(org.springframework.dao.EmptyResultDataAccessException ex){throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Ticket not found");}}
    private boolean reopenAllowed(Map<String,Object> ticket){Object at=ticket.get("resolvedAt");if(at==null)return false;java.time.LocalDateTime resolved=((java.sql.Timestamp)at).toLocalDateTime();return !resolved.plusDays(7).isBefore(java.time.LocalDateTime.now(java.time.ZoneOffset.UTC));}
    private void notifyCustomer(long customer,String title,String body){notifications.notify(customer,title,body,null,true);}
    private long customerId(String email){try{return jdbc.queryForObject("SELECT cp.user_id FROM customer_profile cp JOIN users u ON u.id=cp.user_id WHERE u.email=? AND u.role='CUSTOMER' AND u.status='ACTIVE' AND cp.approval_status='APPROVED' AND u.deleted_at IS NULL",Long.class,email);}catch(org.springframework.dao.EmptyResultDataAccessException ex){throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Customer account is not approved");}}
    private long actorId(String email){try{return jdbc.queryForObject("SELECT id FROM users WHERE email=? AND role='HELP_SUPPORT' AND status='ACTIVE' AND deleted_at IS NULL",Long.class,email);}catch(org.springframework.dao.EmptyResultDataAccessException ex){throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Support account is not active");}}
    private long count(String status){return jdbc.queryForObject("SELECT COUNT(*) FROM ticket WHERE status=?",Long.class,status);}
    private void validatePage(int page,int size){if(page<0||size<1||size>100||(long)page*size>Integer.MAX_VALUE)throw bad("Page must be non-negative and size must be between 1 and 100");}
    private void audit(long actor,String action,String entity,long id,String ip,Object oldValue,Object newValue){try{jdbc.update("INSERT INTO audit_log(actor_id,action,entity_type,entity_id,ip_address,old_value,new_value) VALUES (?,?,?,?,?,CAST(? AS JSON),CAST(? AS JSON))",actor,action,entity,String.valueOf(id),ip,oldValue==null?null:json.writeValueAsString(oldValue),newValue==null?null:json.writeValueAsString(newValue));}catch(JsonProcessingException e){throw new IllegalStateException("Could not write audit record",e);}}
    private ResponseStatusException bad(String message){return new ResponseStatusException(HttpStatus.BAD_REQUEST,message);}private ResponseStatusException conflict(String message){return new ResponseStatusException(HttpStatus.CONFLICT,message);}
    public record PageResult(List<Map<String,Object>> items,int page,int size,long total){}
}
